<?php declare(strict_types=1);require __DIR__.'/_bootstrap.php';require_admin();$pageTitle='Messages';$active='contacts';if(is_post()){verify_csrf($_POST['csrf']??'');$id=filter_input(INPUT_POST,'id',FILTER_VALIDATE_INT);$action=$_POST['action']??'';if($id&&$action==='status'){$st=$_POST['status']??'read';if(in_array($st,['read','unread'],true)){$pdo->prepare('UPDATE contact_messages SET status=?,read_at=? WHERE id=?')->execute([$st,$st==='read'?date('Y-m-d H:i:s'):null,$id]);flash('success','Message status updated.');}}elseif($id&&$action==='delete'){$pdo->prepare('DELETE FROM contact_messages WHERE id=?')->execute([$id]);flash('success','Message deleted.');}redirect_to('contacts.php');}$messages=$pdo->query('SELECT * FROM contact_messages ORDER BY id DESC LIMIT 300')->fetchAll();require __DIR__.'/includes/layout.php';?><div class="panel"><div class="panel-head"><h2>Customer enquiries</h2><span style="color:#687589;font-size:12px"><?=count($messages)?> shown</span></div><div class="table-wrap"><table><thead><tr><th>Name</th><th>Contact</th><th>Message</th><th>Status</th><th>Date</th><th>Actions</th></tr></thead><tbody><?php foreach($messages as $m): ?><tr><td><b><?=e($m['fullname'])?></b></td><td><?=e($m['phone']??'')?><br><?=e($m['email']??'')?></td><td style="white-space:normal;min-width:300px"><?=nl2br(e($m['message']))?></td><td><span class="badge <?=e($m['status'])?>"><?=e($m['status'])?></span></td><td><?=e($m['created_at'])?></td><td><div class="actions"><form method="post"><input type="hidden" name="csrf" value="<?=e(csrf_token())?>"><input type="hidden" name="id" value="<?= (int)$m['id'] ?>"><input type="hidden" name="action" value="status"><input type="hidden" name="status" value="<?=$m['status']==='read'?'unread':'read'?>"><button class="btn btn-light"><?=$m['status']==='read'?'Unread':'Mark read'?></button></form><form method="post"><input type="hidden" name="csrf" value="<?=e(csrf_token())?>"><input type="hidden" name="id" value="<?= (int)$m['id'] ?>"><input type="hidden" name="action" value="delete"><button class="btn btn-danger" data-confirm="Delete this message?">Delete</button></form></div></td></tr><?php endforeach;?></tbody></table></div></div><?php require __DIR__.'/includes/footer.php';?>
